typedef unsigned int Word; // 32-bit word

Word word_mux_2to1(Word A, Word B, int Sel) {
    // Selects a full data word based on a control signal (Sel)
    // Avoids branch prediction costs in hardware simulation
    // M = all 1s if Sel=1, all 0s if Sel=0
    Word M = (Word) -Sel;

    // (A AND NOT M) OR (B AND M)
    return (A & (~M)) | (B & M);
}

