#define N_BITS 16
typedef unsigned short DataWord;

int n_bit_comparator_EQ(DataWord A, DataWord B) {
    // Compares two data words bitwise (parallel operation)
    // Result is 1 if A == B (all bits are equal)
    DataWord diff = A ^ B; // XOR operation

    // Check if any bit in the difference is set
    return (diff == 0); 
}

