typedef unsigned long long Word64;
typedef unsigned int Word32;

Word32 ripple_carry_adder(Word32 A, Word32 B, int C_in, int* C_out) {
    // Models parallel 32-bit addition with carry generation
    Word64 sum = (Word64)A + (Word64)B + C_in;
    const int W = 32;

    *C_out = (sum >> W) & 1; // Capture carry out
    return (Word32)sum;      // Truncate to output word size
}
